import{_ as a,o as r,c as i,ao as t}from"./chunks/framework.CpiZ2d4R.js";const h=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"developer/roadmap.md","filePath":"developer/roadmap.md","lastUpdated":null}'),o={name:"developer/roadmap.md"};function n(l,e,s,p,m,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="Roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#Roadmap" aria-label="Permalink to &quot;Roadmap {#Roadmap}&quot;">​</a></h1><p>The roadmap is intentionally short and is not tied to version numbers. Correctness remains a release requirement; the main open target is now performance.</p><h2 id="Main-priority:-performance" tabindex="-1">Main priority: performance <a class="header-anchor" href="#Main-priority:-performance" aria-label="Permalink to &quot;Main priority: performance {#Main-priority:-performance}&quot;">​</a></h2><ul><li><p>Use the <a href="./../benchmarks/performance">performance benchmarks</a> as the baseline for optimization work and keep every result reproducible through the <a href="./../benchmarks/reproduce">benchmark workflow</a>.</p></li><li><p>Reduce fitting time, especially for the default family search. The practical goal is to close the gap to <code>rvinecopulib</code> and, where possible, match or outperform it without weakening correctness or API clarity.</p></li><li><p>Profile before optimizing. Performance changes should show a measurable improvement in the benchmark suite while the <a href="./../benchmarks/correctness">correctness gate</a> remains green.</p></li><li><p>Prioritize pair-family selection, repeated likelihood and h-function calculations, Student-t bottlenecks, allocations, and reusable intermediate state.</p></li><li><p>Explore parallel family or edge fitting only where benchmarks show a clear benefit.</p></li></ul><p>Performance work is a particularly useful contribution area. Profiling results, lower-allocation kernels, optimizer improvements, and focused pull requests with before/after benchmark numbers are welcome.</p><h2 id="Near-term-improvements" tabindex="-1">Near-term improvements <a class="header-anchor" href="#Near-term-improvements" aria-label="Permalink to &quot;Near-term improvements {#Near-term-improvements}&quot;">​</a></h2><ul><li><p>Improve fitted-model summaries and diagnostics.</p></li><li><p>Reduce allocations in repeated vine evaluation and conditional-state propagation.</p></li><li><p>Reuse or fuse intermediate computations when density and h-functions require the same quantities.</p></li><li><p>Add data-driven truncation-depth selection with a clear statistical criterion.</p></li><li><p>Keep fitting controls expressive without making the default API heavier.</p></li></ul><h2 id="Later" tabindex="-1">Later <a class="header-anchor" href="#Later" aria-label="Permalink to &quot;Later {#Later}&quot;">​</a></h2><ul><li><p>Observation weights and deliberate missing-data handling.</p></li><li><p>Additional nonparametric pair-copula fitting routes.</p></li><li><p>Carefully scoped support for non-simplified vine models.</p></li></ul>',9)])])}const u=a(o,[["render",n]]);export{h as __pageData,u as default};
